import json,pathlib,re,statistics,sys
root=pathlib.Path(sys.argv[1]);d=json.loads((root/'paired-smoke-result.json').read_text()); rows=[]
for pair in d['pairs']:
 times={}
 for variant in ['before','after']:
  sample=pair['results'][variant]['samples'][0];inventory=set(sample.get('tests',[]));stack=[];out={}
  for line in (root/f"pair-{pair['index']+1}"/variant/'sample-1/stdout.log').read_text().splitlines():
   line=re.sub(r'\x1b\[[0-9;]*m','',line);m=re.match(r'^(\s*)✔ (.*?)(?: \((\d+)ms\))?$',line)
   if m:
    indent=len(m[1]);name=' '.join([v for i,v in stack if i<indent]+[m[2]]);assert name in inventory,(name,'not in inventory');out[name]=int(m[3]) if m[3] else None
   elif line.strip() and not line.lstrip().startswith(('-','✔')) and not re.search(r'\d+ (passing|pending|failing)',line):
    indent=len(line)-len(line.lstrip());candidate=[(i,v)for i,v in stack if i<indent]+[(indent,line.strip())];prefix=' '.join(v for i,v in candidate)
    if any(name.startswith(prefix+' ')for name in inventory):stack=candidate
  assert set(out)==inventory,(pair['index'],variant,len(out),len(inventory));times[variant]=out
 rows.append({'index':pair['index']+1,'elapsed':{v:pair['results'][v]['samples'][0]['elapsedMs'] for v in ['before','after']},'tests':times})
summary=[]
for name in rows[0]['tests']['before']:
 values={v:[r['tests'][v][name] for r in rows if r['tests'][v][name] is not None]for v in ['before','after']}
 if not all(values.values()):continue
 b,a=(statistics.median(values[v])for v in ['before','after']);delta=statistics.mean((r['tests']['after'][name]or 0)-(r['tests']['before'][name]or 0)for r in rows);summary.append({'name':name,'beforeMedianMs':b,'afterMedianMs':a,'meanPairedDeltaMs':delta,'changePct':(a/b-1)*100 if b else None})
output={'source':str(root),'run':d['commits'],'comparison':d['comparison'],'rows':rows,'summary':summary};(root/'per-test-analysis.json').write_text(json.dumps(output,indent=2)+'\n')
for label,key,reverse in [('Longest tests','beforeMedianMs',True),('Largest mean improvements','meanPairedDeltaMs',False),('Largest mean regressions','meanPairedDeltaMs',True)]:
 print(label)
 for r in sorted(summary,key=lambda r:r[key],reverse=reverse)[:12]:print(round(r['beforeMedianMs']),round(r['afterMedianMs']),round(r['meanPairedDeltaMs']),r['name'].replace('VSCode Smoke Tests (Electron) ',''))
print('Median summed test times',{v:statistics.median(sum(x or 0 for x in r['tests'][v].values()) for r in rows)for v in ['before','after']})
print('Median non-case wall time',{v:statistics.median(r['elapsed'][v]-sum(x or 0 for x in r['tests'][v].values()) for r in rows)for v in ['before','after']})
